const rowBeforeArtworkRecovery=row;row=function(t,i){return rowBeforeArtworkRecovery(t,i).replace(/<img class="art"[^>]*>/,`<button class="art-button" data-open-track="${esc(t.id)}" aria-label="Слушать ${esc(t.title)} в большом плеере"><img class="art" src="${esc(coverSource(t.cover,image(i)))}" alt="Обложка ${esc(t.title)}" loading="lazy" data-cover-fallback="${image(i)}"><span>${playerIcon('expand')}</span></button>`)};
document.addEventListener('error',e=>{const img=e.target;if(img.tagName!=='IMG')return;const fallback=img.dataset.coverFallback||image(0);if(img.getAttribute('src')!==fallback){img.src=fallback;img.dataset.coverFallback=fallback}},true);
$('#nowTitle').tabIndex=0;$('#nowTitle').setAttribute('role','button');$('#nowTitle').setAttribute('aria-label','Открыть большой плеер');$('#nowTitle').title='Сейчас играет';
const nowPlayingShortcut=document.createElement('button');nowPlayingShortcut.id='nowPlayingShortcut';nowPlayingShortcut.setAttribute('aria-label','Открыть большой плеер');nowPlayingShortcut.title='Сейчас играет · Ctrl+L';nowPlayingShortcut.innerHTML=playerIcon('expand');document.querySelector('.header-right').prepend(nowPlayingShortcut);
document.addEventListener('click',e=>{const b=e.target.closest('[data-open-track],#nowTitle,#nowPlayingShortcut');if(!b)return;if(b.dataset.openTrack){const t=find(b.dataset.openTrack);if(!t)return;if(current?.id!==t.id){if(t.playable===false){audio.pause();audio.removeAttribute('src');audio.load();current=t;sync();toast('Карточка трека открыта. Для прослушивания найди доступную версию.')}else if(page==='wave'){startWave(t)}else{const items=page==='favorites'?(favoriteMode==='playlists'?ownPlaylists.find(p=>p.id===playlistSelected)?.items||[]:favoriteItems()):page==='search'?searchItems:tracks;queue=items.filter(t=>t.playable!==false);play(t)}}}openFocus()});
const playBeforePreviewRecovery=$('#play').onclick;$('#play').onclick=()=>{if(current?.playable===false){findAlternative(current);return}return playBeforePreviewRecovery()};
$('#nowTitle').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openFocus()}});
// Keep the metadata aligned even when a title wraps to a second line.
const updateFocusBeforeArtworkRecovery=updateFocusTrack;updateFocusTrack=function(){updateFocusBeforeArtworkRecovery();if(!focusOpen||!current)return;const cover=$('#focusCover'),backdrop=$('#focusBackdrop');if(cover)cover.style.backgroundImage=`url("${coverSource(current.cover,image(0))}"),url("${image(0)}")`;if(backdrop)backdrop.style.backgroundImage=`url("${coverSource(current.cover,image(0))}"),url("${image(0)}")`};
const prefetchedAudio=new Set();let prefetchBusy=false;async function prepareNextAudio(){if(!backend||!current||prefetchBusy)return;const i=queue.findIndex(t=>t.id===current.id),t=queue.slice(i+1,i+3).find(t=>t.source==='soundcloud'&&t.playable!==false&&!prefetchedAudio.has(t.id));if(!t)return;prefetchBusy=true;try{const d=await api('stream/preload',{method:'POST',body:JSON.stringify({source:t.source,sourceId:String(t.sourceId||t.id.split(':').pop())})});if(d.warming)prefetchedAudio.add(t.id)}catch{}finally{prefetchBusy=false}}audio.addEventListener('playing',prepareNextAudio);let prefetchStamp=0;audio.addEventListener('timeupdate',()=>{if(!audio.paused&&Date.now()-prefetchStamp>15000){prefetchStamp=Date.now();prepareNextAudio()}});
if(!localStorage.getItem('soulroom.artworkRecovery022')){appearance.artwork=true;applyAppearance();localStorage.setItem('soulroom.artworkRecovery022','1')}

